  ('fuchtl', 'Fuchtl', '', '', '', 'Grundwortschatz Wienerisch', 'Fuchtel', '[{"kategorie": "wörtlich", "text": "\"Fuchtel\" (vom mittelhochdeutschen \"vuchten\"=\"fechten\" bzw. \"wild schlagen\")"}, {"kategorie": "hist.", "text": "\"Fuchtel\" (\"Fechtdegen mit breiter Klinge, der zur Bestrafung von Soldaten benutzt wurde), \"Zuchtdegen\", \"Drilldegen\" (die Fuchtel diente weniger dem Kampf als der Zucht, Übung und Strafe und war insbesondere im 18. und 19. Jahrhundert gebräuchlich. Der Name leitet sich vom Verb fuchteln ab und verweist auf die schlagende, ausholende Bewegung der Waffe), \"militärisches Zuchtinstrument\""}, {"kategorie": "in Bezug auf Personen, geschlechtsneutral", "text": "\"nervige, herumfuchtelnde Person\", \"Quälgeist\", \"Nervensäge\""}, {"kategorie": "in Bezug auf Frauen", "text": "\"Keifhexe\" (zänkisches aufbrausendes Frauenzimmer), \"Krawallschachtel\" (keifendes jähzorniges  Weib, das keinen Widerspruch duldet), \"Streithenne\", \"Drachen\" (herrschsüchtige Frau, die ihren Mann unter ihrer Fuchtel hat), \"Furie\" (dominante herrische Frau), \"Zicke\", \"Tussi\", [[Funsn]], [[Traumpä]], [[Luada]]"}]'::jsonb, 'A so a narrische Fuchtl!'),
  ('fuchtig', 'fuchtig', '', '', '', 'Grundwortschatz Wienerisch', 'fuchtig', '[{"kategorie": "wörtlich", "text": "\"zornig\" (vom mittelhochdeutschen \"vorhtic\"=\"fuchtig\")"}, {"kategorie": "allg.", "text": "aufgebracht, zornig, wütend, böse, [[grawutisch]]"}]'::jsonb, 'De Leit woan mea ois fuchtig, wia da Schiri an Ööfa pfiffn hod!'),
  ('fuchtln', 'fuchtln', '', '', '', 'Grundwortschatz Wienerisch', 'fuchteln', '[{"kategorie": "wörtlich", "text": "\"fuchteln\" (vom mittelhochdeutschen \"vuchten\"=\"hin- und herschwingen\" [ursprünglich: \"''mit der [[Fuchtel]] schlagen\"=\"die Degenklinge hin- und herbewegen\")"}, {"kategorie": "allg.", "text": "\"einen Gegenstand in der Luft hektisch hin und herbewegen\", \"hin- und herschwingen\", \"hin und herwedeln\", \"hin und herschwenken\""}, {"kategorie": "", "text": "mit den Händen wild herumgestikulieren, mit den Armen herumrudern, herumwedeln, herumschwingen"}]'::jsonb, 'Dea Wichsa hod sofuat min Messa gfuchtld, ois warada wea!'),
  ('umadumfuchtln', 'umadumfuchtln', '', '', '', 'Grundwortschatz Wienerisch', 'umadumfuchteln', '[{"kategorie": "wörtlich", "text": "\"herumfuchteln\" (Kompositum aus dem abtrennbaren Präfix [[umadum]]=\"herum\" und \"fuchteln\"=\"hin- und herschwingen\")"}, {"kategorie": "allg.", "text": "\"einen Gegenstand in der Luft hektisch hin- und herbewegen\", \"hin- und herschwingen\", \"hin- und herwedeln\", \"hin- und herschwenken\""}, {"kategorie": "allg.", "text": "mit den Armen unkontrolliert herumrudern,  wild um sich gestikulieren, mit den Armen herumwedeln"}]'::jsonb, 'Dea fuchtld min Eckdfaanl umadum, ois warads de Maastaschoin!'),
