  ('gansl', 'Gansl', '', '', '', 'Grundwortschatz Wienerisch', 'Gansl', '[{"kategorie": "wörtlich", "text": "\"Gänslein\" (Verkleinerungsform von \"Gans\", vom mittelhochdeutschen \"gans\"=\"Gans\")"}, {"kategorie": "zool.", "text": "Gans, Entenvogel, Gänserich, Ganser"}, {"kategorie": "Gastronomie", "text": "\"gebratene Gans\", [[Martinigansl]]"}, {"kategorie": "fig., scherzhaft für", "text": "\"dumm schnatterndes Mädchen\", Göre, Tussi, \"dummes Blondchen\""}]'::jsonb, 'Wos waassn des Gansl scho vom Leebm?'),
