  ('ganslhaut', 'Ganslhaut', '', '', '', '', 'Ganselhaut', '[{"kategorie": "wörtlich", "text": "\"Gänsehaut\" (Determinativkompositum aus \"Gansel\"=\"Gans\" und \"Haut\"=\"Hautkribbeln\")"}, {"kategorie": "allg.", "text": "Hautkribbeln, Schauder, \"Hühnchenhaut\""}]'::jsonb, 'Do kriag I a Ganslhaut!'),
